<template>
  <el-dialog :modelValue="modelValue" :title="editingId ? '编辑制作模板' : '保存制作模板'" width="min(920px, 96vw)" appendToBody :closeOnClickModal="false" :closeOnPressEscape="false" :beforeClose="closeEditor" :showClose="!saving" @update:modelValue="emit('update:modelValue', $event)">
    <form ref="form" class="templateEditor" novalidate @submit.prevent="save">
      <div v-if="error" ref="errorBox" class="errorText" tabindex="-1" role="alert">{{ error }}<button v-for="issue in issues" :key="issue.path" type="button" @click="focusField(issue.path)">{{ issue.message }}</button><el-button v-if="conflict" :disabled="saving" @click="refresh">刷新并核对</el-button><el-button v-if="conflict" :disabled="saving" @click="saveCopy">草稿另存副本</el-button></div>
      <section v-if="latest" class="latestTemplate"><h3>最新模板：{{ latest.title }}</h3><productionTemplateDetail :definition="latest" /><p>当前草稿保留。载入会替换草稿，也可以另存副本。</p><el-button @click="loadLatest">载入最新内容，替换草稿</el-button></section>
      <fieldset :disabled="saving"><div class="fieldGrid"><label>模板标题<input v-model="draft.title" data-field="title" aria-label="模板标题" maxlength="200" /></label><label>标签，以逗号分隔<input v-model="tagText" data-field="tags" aria-label="模板标签" /></label></div><label>用途说明<textarea v-model="draft.description" data-field="description" aria-label="模板用途说明" rows="2" maxlength="10000" /></label>
        <details open><summary>输入要求 · {{ draft.inputs.length }} 项</summary><p class="hint">在镜头或资料中使用双花括号引用变量，例如 <code v-pre>{{brief}}</code>。默认值保存在本机，导出时可清空。</p><div v-for="(item, index) in draft.inputs" :key="index" class="record"><div class="fieldGrid"><label>变量名称<input v-model="item.key" :data-field="'inputs.' + index" :aria-label="'输入' + (index + 1) + '变量名称'" maxlength="64" /></label><label>显示名称<input v-model="item.label" :aria-label="'输入' + (index + 1) + '显示名称'" maxlength="100" /></label></div><label>默认值<textarea v-model="item.defaultValue" :aria-label="'输入' + (index + 1) + '默认值'" rows="2" maxlength="10000" /></label><div class="rowActions"><label class="toggle"><input v-model="item.required" type="checkbox" />必填</label><el-button @click="draft.inputs.splice(index, 1)">移除此输入</el-button></div></div><el-button :disabled="draft.inputs.length >= 40" @click="addInput">添加输入</el-button></details>
        <details><summary>推荐流程 · {{ draft.workflow.length }} 步</summary><div v-for="(step, index) in draft.workflow" :key="index" class="record"><label>步骤名称<input v-model="step.title" :data-field="'workflow.' + index" :aria-label="'步骤' + (index + 1) + '名称'" maxlength="200" /></label><label>操作说明<textarea v-model="step.description" :aria-label="'步骤' + (index + 1) + '说明'" rows="2" maxlength="10000" /></label><div class="rowActions"><el-button :disabled="!index" @click="move(draft.workflow, index, -1)">上移步骤</el-button><el-button :disabled="index === draft.workflow.length - 1" @click="move(draft.workflow, index, 1)">下移步骤</el-button><el-button :disabled="draft.workflow.length <= 1" @click="draft.workflow.splice(index, 1)">移除步骤</el-button></div></div><el-button :disabled="draft.workflow.length >= 30" @click="draft.workflow.push({ title: '新步骤', description: '' })">添加步骤</el-button></details>
        <details><summary>模型位置 · {{ draft.modelSlots.length }} 项</summary><p class="hint">模板保存媒体类型与可选模型提示；每次应用时重新选择实际渠道。删除已使用的位置前，先修改对应镜头。</p><div v-for="(slot, index) in draft.modelSlots" :key="slot.key" class="record"><div class="fieldGrid"><label>位置名称<input v-model="slot.label" :data-field="'modelSlots.' + index" :aria-label="'模型位置' + (index + 1) + '名称'" maxlength="200" /></label><label>创作类型<select v-model="slot.mediaType" :aria-label="slot.label + '创作类型'"><option value="image">图片</option><option value="video">视频</option><option value="audio">音频</option></select></label></div><label>用途<textarea v-model="slot.purpose" :aria-label="slot.label + '用途'" rows="2" maxlength="2000" /></label><label>可选模型编号提示<input :value="slot.suggestedModelId ?? ''" :aria-label="slot.label + '模型编号提示'" maxlength="256" @input="setHint(slot, ($event.target as HTMLInputElement).value)" /></label><el-button :disabled="draft.modelSlots.length <= 1 || allNodes.some(node => node.modelSlotKey === slot.key)" @click="draft.modelSlots.splice(index, 1)">移除此模型位置</el-button></div><el-button :disabled="draft.modelSlots.length >= 16" @click="addSlot">添加模型位置</el-button></details>
        <details><summary>样例制作单元与输出</summary><label>制作单元名称<input v-model="draft.example.name" data-field="example.name" aria-label="样例制作单元名称" maxlength="200" /></label><div class="fieldGrid"><label>宽度<input v-model.number="draft.example.output.width" data-field="example.output" type="number" min="64" max="8192" aria-label="样例输出宽度" /></label><label>高度<input v-model.number="draft.example.output.height" type="number" min="64" max="8192" aria-label="样例输出高度" /></label><label>帧率<input v-model.number="draft.example.output.frameRate" type="number" min="1" max="120" aria-label="样例输出帧率" /></label></div><p class="hint">这些值用于制作单元与剪辑输出，生成模型的尺寸和时长需要在节点中确认。</p></details>
        <details><summary>参考素材与固定版本 · {{ draft.example.assets.length }} 项</summary><div v-for="(asset, index) in draft.example.assets" :key="asset.key" class="record"><div class="fieldGrid"><label>素材名称<input v-model="asset.name" :data-field="'example.assets.' + index" :aria-label="'素材' + (index + 1) + '名称'" maxlength="200" /></label><label>素材类别<select v-model="asset.kind" :aria-label="asset.name + '类别'"><option v-for="(label, kind) in assetKinds" :key="kind" :value="kind">{{ label }}</option></select></label></div><div v-for="(version, versionIndex) in asset.versions" :key="version.key" class="versionRecord"><strong>版本 {{ versionIndex + 1 }}</strong><label>父版本<select v-model="version.parentKey" :aria-label="asset.name + '版本' + (versionIndex + 1) + '父版本'"><option :value="undefined">无父版本</option><option v-for="parent in asset.versions.filter(item => item.key !== version.key)" :key="parent.key" :value="parent.key">版本 {{ asset.versions.indexOf(parent) + 1 }}</option></select></label><label>参考文字<textarea v-model="version.text" :aria-label="asset.name + '版本' + (versionIndex + 1) + '参考文字'" rows="3" maxlength="100000" /></label><label>版本说明<textarea v-model="version.description" :aria-label="asset.name + '版本' + (versionIndex + 1) + '说明'" rows="2" maxlength="10000" /></label><el-button :disabled="asset.versions.length <= 1 || versionUsed(asset.key, version.key)" @click="asset.versions.splice(versionIndex, 1)">移除此版本</el-button></div><div class="rowActions"><el-button :disabled="asset.versions.length >= 16" @click="addVersion(asset)">添加版本</el-button><el-button :disabled="asset.versions.some(version => versionUsed(asset.key, version.key))" @click="draft.example.assets.splice(index, 1)">移除此素材</el-button></div></div><el-button :disabled="draft.example.assets.length >= 64" @click="addAsset">添加参考素材</el-button></details>
        <details><summary>参考文件要求 · {{ draft.mediaInputs.length }} 项</summary><p class="hint">模板记录文件要求，应用时选择目标项目中的文件；不把原文件或原路径存入可分享模板。</p><div v-for="(item, index) in draft.mediaInputs" :key="item.key" class="record"><label>文件说明名称<input v-model="item.label" :data-field="'mediaInputs.' + index" :aria-label="'参考文件' + (index + 1) + '名称'" maxlength="200" /></label><div class="fieldGrid"><label>文件类型<select v-model="item.mediaType" :aria-label="item.label + '文件类型'"><option value="image">图片</option><option value="video">视频</option><option value="audio">音频</option></select></label><label>对应素材版本<select :value="item.assetKey + ':' + item.versionKey" :aria-label="item.label + '对应版本'" @change="setMediaVersion(item, ($event.target as HTMLSelectElement).value)"><option v-for="version in versions" :key="version.value" :value="version.value">{{ version.label }}</option></select></label></div><label>输入说明<textarea v-model="item.description" :aria-label="item.label + '输入说明'" rows="2" maxlength="2000" /></label><div class="rowActions"><label class="toggle"><input v-model="item.required" type="checkbox" />必须提供文件</label><el-button @click="draft.mediaInputs.splice(index, 1)">移除文件要求</el-button></div></div><el-button :disabled="!versions.length || draft.mediaInputs.length >= 32" @click="addMedia">添加文件要求</el-button></details>
        <details open><summary>镜头结构 · {{ draft.example.shots.length }} 个镜头</summary><details v-for="(shot, index) in draft.example.shots" :key="shot.key" class="shotRecord"><summary>{{ index + 1 }}. {{ shot.title }}</summary><label>镜头标题<input v-model="shot.title" :data-field="'example.shots.' + index" :aria-label="'镜头' + (index + 1) + '标题'" maxlength="200" /></label><div class="fieldGrid"><label>模型位置<select v-model="shot.modelSlotKey" :aria-label="'镜头' + (index + 1) + '模型位置'"><option v-for="slot in draft.modelSlots" :key="slot.key" :value="slot.key">{{ slot.label }}</option></select></label><label>预计成片秒数<input v-model.number="shot.expectedDuration" :aria-label="'镜头' + (index + 1) + '预计秒数'" type="number" min="0.01" max="3600" step="any" /></label></div><label>剧情<textarea v-model="shot.story" :aria-label="'镜头' + (index + 1) + '剧情'" rows="2" maxlength="100000" /></label><label>对白<textarea v-model="shot.dialogue" :aria-label="'镜头' + (index + 1) + '对白'" rows="2" maxlength="100000" /></label><label>生成提示词<textarea v-model="shot.prompt" :aria-label="'镜头' + (index + 1) + '提示词'" rows="4" maxlength="100000" /></label><fieldset class="referenceChoices"><legend>引用固定版本</legend><label v-for="version in versions" :key="version.value" class="toggle"><input type="checkbox" :checked="hasReference(shot, version.value)" @change="toggleReference(shot, version.value)" />{{ version.label }}</label><label v-for="reference in shot.references" :key="reference.assetKey + ':' + reference.versionKey">引用用途<input v-model="reference.role" :aria-label="'镜头' + (index + 1) + '引用' + reference.assetKey + reference.versionKey + '用途'" maxlength="200" /></label></fieldset><div class="rowActions"><el-button :disabled="!index" @click="move(draft.example.shots, index, -1)">上移镜头</el-button><el-button :disabled="index === draft.example.shots.length - 1" @click="move(draft.example.shots, index, 1)">下移镜头</el-button><el-button :disabled="draft.example.shots.length <= 1" @click="draft.example.shots.splice(index, 1)">移除此镜头</el-button></div></details><el-button :disabled="draft.example.shots.length >= 200" @click="addShot">添加镜头</el-button></details>
        <details><summary>辅助创作节点 · {{ draft.example.generationNodes.length }} 项</summary><div v-for="(node, index) in draft.example.generationNodes" :key="node.key" class="record"><label>节点名称<input v-model="node.title" :data-field="'example.generationNodes.' + index" :aria-label="'辅助节点' + (index + 1) + '名称'" maxlength="200" /></label><label>模型位置<select v-model="node.modelSlotKey" :aria-label="node.title + '模型位置'"><option v-for="slot in draft.modelSlots" :key="slot.key" :value="slot.key">{{ slot.label }}</option></select></label><label>提示词<textarea v-model="node.prompt" :aria-label="node.title + '提示词'" rows="3" maxlength="100000" /></label><label v-for="version in versions" :key="version.value" class="toggle"><input type="checkbox" :checked="hasReference(node, version.value)" @change="toggleReference(node, version.value)" />{{ version.label }}</label><el-button @click="draft.example.generationNodes.splice(index, 1)">移除此辅助节点</el-button></div><el-button :disabled="draft.example.generationNodes.length >= 32" @click="addNode">添加辅助节点</el-button></details>
      </fieldset><div class="editorActions"><el-button :disabled="saving" @click="closeEditor(() => emit('update:modelValue', false))">取消</el-button><el-button nativeType="submit" type="primary" :loading="saving" :disabled="!store.loaded || store.busy || !!latest">保存制作模板</el-button></div>
    </form>
  </el-dialog>
</template>

<script setup lang="ts">
import { computed, nextTick, reactive, ref, watch } from "vue";
import { ElMessageBox } from "element-plus";
import { productionTemplateSchema, type ProductionTemplate } from "@toonflow/server/productionTemplates";
import productionTemplateDetail from "./productionTemplateDetail.vue";
import { productionTemplateError, useProductionTemplateLibraryStore } from "@/stores/productionTemplates";
const props = defineProps<{ modelValue: boolean; entryId?: string; seed?: ProductionTemplate }>();
const emit = defineEmits<{ "update:modelValue": [value: boolean]; saved: [id: string] }>();
const store = useProductionTemplateLibraryStore(); const saving = ref(false); const error = ref(""); const conflict = ref(false); const latest = ref<ProductionTemplate>(); const tagText = ref(""); const editingId = ref<string>();
const form = ref<HTMLFormElement>(); const errorBox = ref<HTMLElement>(); const issues = ref<{ path: string; message: string }[]>([]);
const assetKinds = { character: "角色", scene: "场景", prop: "道具", image: "图片", video: "视频", audio: "音频", text: "文本" };
function blank(): ProductionTemplate { return { title: "新制作模板", description: "", tags: [], inputs: [{ key: "brief", label: "创作要求", defaultValue: "", required: true }], mediaInputs: [], workflow: [{ title: "确认输入与参考", description: "先核对镜头，再选择实际模型并检查能力和费用。" }], modelSlots: [{ key: "image", label: "分镜图片", mediaType: "image", purpose: "创作分镜图片" }], example: { name: "新制作单元", output: { width: 1280, height: 720, frameRate: 24 }, assets: [], shots: [{ key: "shot1", title: "镜头1", prompt: "{{brief}}", modelSlotKey: "image", references: [], story: "", dialogue: "", expectedDuration: 3 }], generationNodes: [] } }; }
const draft = reactive<ProductionTemplate>(blank());
const definition = computed(() => ({ ...draft, tags: [...new Set(tagText.value.split(/[,，\n]/).map(tag => tag.trim()).filter(Boolean))] }));
const allNodes = computed(() => [...draft.example.shots, ...draft.example.generationNodes]);
const versions = computed(() => draft.example.assets.flatMap(asset => asset.versions.map((version, index) => ({ value: `${asset.key}:${version.key}`, label: `${asset.name} · 版本${index + 1}` }))));
let revision = 0; let baseline = "";
function setDraft(value: ProductionTemplate) { Object.assign(draft, JSON.parse(JSON.stringify(value))); tagText.value = draft.tags.join(", "); baseline = JSON.stringify(definition.value); }
watch(() => props.modelValue, open => { if (!open) return; editingId.value = props.entryId; setDraft(props.seed ?? blank()); revision = store.library.revision; error.value = ""; issues.value = []; conflict.value = false; latest.value = undefined; }, { immediate: true });
function nextKey(prefix: string, keys: string[]) { let index = 1; while (keys.includes(prefix + index)) index++; return prefix + index; }
function addInput() { const key = nextKey("input", draft.inputs.map(item => item.key)); draft.inputs.push({ key, label: "新增输入", defaultValue: "", required: true }); }
function addSlot() { draft.modelSlots.push({ key: nextKey("model", draft.modelSlots.map(item => item.key)), label: "新增模型位置", mediaType: "image", purpose: "" }); }
function setHint(slot: ProductionTemplate["modelSlots"][number], value: string) { if (value.trim()) slot.suggestedModelId = value; else delete slot.suggestedModelId; }
function addAsset() { draft.example.assets.push({ key: nextKey("asset", draft.example.assets.map(item => item.key)), name: "新增参考", kind: "character", versions: [{ key: "version1", text: "", description: "参考资料待补充" }] }); }
function addVersion(asset: ProductionTemplate["example"]["assets"][number]) { asset.versions.push({ key: nextKey("version", asset.versions.map(item => item.key)), parentKey: asset.versions.at(-1)?.key, text: "", description: "参考资料待补充" }); }
function versionUsed(assetKey: string, versionKey: string) { return allNodes.value.some(node => node.references.some(item => item.assetKey === assetKey && item.versionKey === versionKey)) || draft.mediaInputs.some(item => item.assetKey === assetKey && item.versionKey === versionKey) || draft.example.assets.find(asset => asset.key === assetKey)?.versions.some(version => version.parentKey === versionKey); }
function addMedia() { const version = versions.value[0]; if (!version) return; const [assetKey, versionKey] = version.value.split(":") as [string, string]; draft.mediaInputs.push({ key: nextKey("media", draft.mediaInputs.map(item => item.key)), label: "新增参考文件", description: "", mediaType: "image", assetKey, versionKey, required: false }); }
function setMediaVersion(item: ProductionTemplate["mediaInputs"][number], value: string) { [item.assetKey, item.versionKey] = value.split(":") as [string, string]; }
function addNode() { draft.example.generationNodes.push({ key: nextKey("node", allNodes.value.map(item => item.key)), title: "辅助创作", prompt: "{{brief}}", modelSlotKey: draft.modelSlots[0]!.key, references: [] }); }
function addShot() { draft.example.shots.push({ key: nextKey("shot", allNodes.value.map(item => item.key)), title: "新镜头", prompt: "{{brief}}", modelSlotKey: draft.modelSlots[0]!.key, references: [], story: "", dialogue: "", expectedDuration: 3 }); }
function move<T>(items: T[], index: number, direction: number) { const item = items.splice(index, 1)[0]!; items.splice(index + direction, 0, item); }
function hasReference(node: ProductionTemplate["example"]["generationNodes"][number], value: string) { return node.references.some(item => `${item.assetKey}:${item.versionKey}` === value); }
function toggleReference(node: ProductionTemplate["example"]["generationNodes"][number], value: string) { const index = node.references.findIndex(item => `${item.assetKey}:${item.versionKey}` === value); if (index >= 0) node.references.splice(index, 1); else { const [assetKey, versionKey] = value.split(":") as [string, string]; node.references.push({ assetKey, versionKey, role: "参考" }); } }
function focusField(path: string) { const element = [...form.value!.querySelectorAll<HTMLElement>("[data-field]")].reverse().find(element => path.startsWith(element.dataset.field!)); if (!element) return; let parent = element.parentElement; while (parent && parent !== form.value) { if (parent instanceof HTMLDetailsElement) parent.open = true; parent = parent.parentElement; } element.focus(); }
async function fail(message: string) { error.value = message; await nextTick(); errorBox.value?.focus(); }
async function save() {
  if (saving.value || (latest.value && editingId.value)) return;
  const parsed = productionTemplateSchema.safeParse(definition.value); issues.value = []; error.value = "";
  if (!parsed.success) { issues.value = parsed.error.issues.map(issue => ({ path: issue.path.join("."), message: issue.message })); await fail("模板尚未保存，请检查以下项目"); return; }
  saving.value = true;
  try { const result = await store.update(editingId.value ? { type: "update", id: editingId.value, definition: parsed.data } : { type: "create", definition: parsed.data }, revision); baseline = JSON.stringify(definition.value); emit("saved", result.entryId); emit("update:modelValue", false); }
  catch (cause) { conflict.value = true; await fail(productionTemplateError(cause)); }
  finally { saving.value = false; }
}
async function refresh() { try { await store.load(); const entry = store.entries.find(item => item.id === editingId.value); if (editingId.value && (!entry || entry.archived)) throw new Error("原模板已归档或不存在，草稿仍保留，可另存副本"); revision = store.library.revision; if (entry && JSON.stringify(entry.definition) !== baseline) { latest.value = JSON.parse(JSON.stringify(entry.definition)); await fail("最新内容与原版本不同，请载入最新内容或另存副本"); } else { conflict.value = false; error.value = ""; } } catch (cause) { await fail(productionTemplateError(cause)); } }
function loadLatest() { if (!latest.value) return; setDraft(latest.value); latest.value = undefined; conflict.value = false; error.value = ""; }
async function saveCopy() { editingId.value = undefined; revision = store.library.revision; latest.value = undefined; await save(); }
async function closeEditor(done: () => void) { if (saving.value) return; if (JSON.stringify(definition.value) !== baseline && !await ElMessageBox.confirm("当前制作模板草稿尚未保存。", "保留模板草稿", { confirmButtonText: "继续编辑", cancelButtonText: "放弃草稿", distinguishCancelAndClose: true }).then(() => false, action => action === "cancel")) return; done(); }
</script>

<style scoped lang="scss">
.templateEditor { font-size: 13px; line-height: 1.7; min-width: 0; fieldset { padding: 0; border: 0; min-width: 0; margin: 0; } label { display: flex; flex-direction: column; gap: 5px; margin: 10px 0; } input:not([type=checkbox]), textarea, select { width: 100%; min-width: 0; box-sizing: border-box; padding: 9px 10px; color: var(--el-text-color-primary); background: var(--el-bg-color); border: 1px solid var(--el-border-color); border-radius: 6px; font: inherit; } textarea { resize: vertical; } .fieldGrid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 16px; } details { border-top: 1px solid var(--el-border-color-light); padding: 14px 0; > summary { cursor: pointer; font-size: 14px; font-weight: 600; overflow-wrap: anywhere; } } .record { padding: 12px 0; border-bottom: 1px solid var(--el-border-color-lighter); } .versionRecord, .referenceChoices { margin-top: 12px; padding: 12px; border: 1px solid var(--el-border-color-light); border-radius: 6px; } .toggle { flex-direction: row; align-items: center; min-height: 36px; } .rowActions, .editorActions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; .el-button { margin-left: 0; } } .editorActions { justify-content: flex-end; padding-top: 20px; } .hint { font-size: 12px; color: var(--el-text-color-secondary); } .errorText { color: var(--el-color-danger); overflow-wrap: anywhere; > button:not(.el-button) { display: block; color: inherit; background: none; border: 0; text-decoration: underline; padding: 5px 0; cursor: pointer; } .el-button { margin: 8px 8px 8px 0; } } .latestTemplate { border: 1px solid var(--el-border-color); padding: 12px; margin-block: 12px; } :focus-visible { outline: 2px solid var(--el-color-primary); outline-offset: 2px; } @media(max-width:600px) { .fieldGrid { grid-template-columns: 1fr; } input:not([type=checkbox]), select, .toggle, .el-button, summary { min-height: 44px; } } }
</style>
